function groupingSets(rows){
  const perRegion = new Map();
  let grand = 0;
  for (const r of rows){
    const cur = (perRegion.get(r.region) || 0) + r.t;
    perRegion.set(r.region, cur);
    grand += cur;
  }
  const out = [...perRegion.entries()].map(([region, total]) => ({ region, total }));
  out.push({ region: null, total: grand });
  return out;
}

